func Require(policy Policy, next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        if !policy.Allows(r.Context(), r) {          // no grant -> deny
            http.Error(w, "forbidden", http.StatusForbidden)
            return
        }
        next.ServeHTTP(w, r)                         // only reachable with a grant
    })
}
mux.Handle("GET /orders/{id}", Require(policy, http.HandlerFunc(getOrder)))
http.ListenAndServe(":8080", Require(policy, mux))   // the default, at the root
